code.cpp:
class Solution {
public:
    int minimumOperations(vector<int>& nums, int start, int goal) {
        vector<int> dist(1001, -1);
        queue<int> q;
        dist[start] = 0;
        q.push(start);
        while (!q.empty()) {
            int x = q.front();
            q.pop();
            for (int num : nums) {
                long long vals[3] = {
                    (long long)x + num,
                    (long long)x - num,
                    (long long)x ^ num
                };
                for (long long v : vals) {
                    if (v == goal) return dist[x] + 1;
                    if (v >= 0 && v <= 1000 && dist[v] == -1) {
                        dist[v] = dist[x] + 1;
                        q.push((int)v);
                    }
                }
            }
        }
        return -1;
    }
};
